            >
              {pendingStageAction === `delete-stage-${stage.id}` ? (
                <>
                  <span className="inline-block w-2 h-2 border-2 border-current border-t-transparent rounded-full animate-spin" />
                  <span>Deleting...</span>
                </>
              ) : (
                'Delete Stage'
              )}
            </button>

